import type { PluginObject } from "@babel/core";
import type { Node } from "@babel/types";

export const preserveNativeFunctions = (): PluginObject => {
  const containingGenerators = new WeakSet<Node>();
  return {
    visitor: {
      Program(path) {
        path.traverse({
          Function(innerPath) {
            if (!innerPath.node.generator) return;
            for (const parent of innerPath.getAncestry()) {
              if (parent.isFunction()) containingGenerators.add(parent.node);
            }
          },
        });
      },
      Function(path) {
        if (!path.node.generator && !containingGenerators.has(path.node)) path.skip();
      },
    },
  };
};
